import json, random, sys, subprocess, time, os

def build(seed=0, natoms=20, B=4, k=2, ntrain_traces=16, train_rows=257,
          probe_rows=129, nquery_traces=1, query_rows=1025, nsrc=16,
          S=1, W=1, schema_kinds=('COUNT',), threshold=False):
    rnd = random.Random(seed)
    schema = []
    for i in range(max(1, len(schema_kinds))):
        t = schema_kinds[i % len(schema_kinds)]
        if t == 'ID':
            schema.append({'name': 'f%d' % i, 'type': 'ID',
                           'values': ['v%d' % j for j in range(4)]})
        elif t == 'FLAG':
            schema.append({'name': 'f%d' % i, 'type': 'FLAG'})
        else:
            schema.append({'name': 'f%d' % i, 'type': t, 'min': 0, 'max': 100})
    nf = len(schema)

    def rand_row():
        vals = []
        for f in schema:
            if f['type'] == 'ID':
                vals.append(rnd.choice(f['values']))
            elif f['type'] == 'FLAG':
                vals.append(rnd.random() < 0.5)
            else:
                vals.append(rnd.randint(0, 100))
        return vals

    def trace(tid, src, n, t0=0):
        rows = []
        for i in range(n):
            rows.append({'t': t0 + i, 'values': rand_row()})
        return {'id': tid, 'source': src, 'rows': rows}

    train = [trace('T%d' % i, 's%d' % (i % nsrc), train_rows) for i in range(ntrain_traces)]
    probes = [trace('P0', 's0', probe_rows)]
    queries = [trace('Q%d' % i, 's0', query_rows) for i in range(nquery_traces)]

    if threshold:
        # atoms: f0 >= threshold  (numeric field), designed to create many eligible clauses
        atoms = []
        for i in range(natoms):
            thr = {'const': 5 * (i + 1), 'type': 'COUNT'}
            atoms.append({'cmp': 'ge', 'left': {'field': 'f0', 'at': 0}, 'right': thr})
    else:
        atoms = []
        for i in range(natoms):
            fi = i % nf
            name = 'f%d' % fi
            if schema[fi]['type'] == 'FLAG':
                left = {'field': name, 'at': rnd.randrange(k)}
                right = {'const': rnd.random() < 0.5, 'type': 'FLAG'}
                atoms.append({'cmp': 'eq', 'left': left, 'right': right})
            elif schema[fi]['type'] == 'ID':
                atoms.append({'cmp': 'eq', 'left': {'field': name, 'at': rnd.randrange(k)},
                              'right': {'const': rnd.choice(schema[fi]['values']), 'type': 'ID'}})
            else:
                if i % 3 == 0:
                    left = {'aggregate': 'mean', 'field': name,
                            'from': 0, 'to': min(k - 1, 1)}
                    right = {'const': rnd.randint(20, 80), 'type': schema[fi]['type']}
                elif i % 3 == 1:
                    left = {'add': [{'field': name, 'at': 0},
                                    {'scale': 2, 'term': {'field': name, 'at': k - 1}}]}
                    right = {'const': rnd.randint(50, 150), 'type': schema[fi]['type']}
                else:
                    left = {'field': name, 'at': rnd.randrange(k)}
                    right = {'const': rnd.randint(10, 90), 'type': schema[fi]['type']}
                atoms.append({'cmp': rnd.choice(['ge', 'le', 'gt', 'lt', 'eq', 'ne']),
                              'left': left, 'right': right})

    return {'version': 1, 'schema': schema, 'window': k, 'atoms': atoms,
            'policy': {'max_width': B, 'min_support': S, 'min_witness': W},
            'train': train, 'probes': probes, 'queries': queries}

if __name__ == '__main__':
    kw = {}
    for a in sys.argv[1:]:
        kk, vv = a.split('=')
        kw[kk] = json.loads(vv) if vv[0] in '0123456789[-{' else vv
    req = build(**kw)
    data = json.dumps(req).encode()
    print('input bytes', len(data), file=sys.stderr)
    t0 = time.time()
    p = subprocess.run([sys.executable, '/app/submission/main.py'], input=data,
                       capture_output=True)
    el = time.time() - t0
    out = p.stdout.decode()
    print('rc=%d wall=%.2fs stderr=%s' % (p.returncode, el, p.stderr.decode()[-300:]))
    try:
        r = json.loads(out)
        print('classes=%d queries=%d' % (len(r['classes']), len(r['queries'])))
        if r['classes']:
            print('max members', max(c['members'] for c in r['classes']),
                  'total members', sum(c['members'] for c in r['classes']))
            from collections import Counter
            print('statuses', Counter(q['status'] for q in r['queries']))
    except Exception as e:
        print('parse fail', e, out[:200])
